            $emp = Employee::where('nama_lengkap', $nama)
                ->where('project_id', $PROJECT_ID)
                ->first();

            if (!$emp) {
                $this->newLine();
                $this->warn("Karyawan tidak ditemukan: {$nama}");
                $skipped++;
                $bar->advance();
                continue;
            }

            foreach ($days as $hari => $nilai) {
                Timesheet::updateOrCreate(
                    [
                        'employee_id' => $emp->id,
                        'tahun'       => $TAHUN,
                        'bulan'       => $BULAN,
                        'hari'        => (int) $hari,
                    ],
                    ['nilai' => $nilai]
                );
                $inserted++;
            }

            $bar->advance();
        }

        $bar->finish();
        $this->newLine(2);
        $this->info("Selesai! {$inserted} entri timesheet disimpan, {$skipped} karyawan tidak ditemukan.");
